            var noteValue: Double = self.realValue
            if self.harmonicType != HarmonicType.Natural && self.harmonicType != HarmonicType.None {
                noteValue -= self.harmonicPitch
            }
            switch self.beat.ottava {
            case Ottavia._15ma:
                noteValue -= 24.0
            case Ottavia._8va:
                noteValue -= 12.0
            case Ottavia.Regular:
                break
            case Ottavia._8vb:
                noteValue += 12.0
            case Ottavia._15mb:
                noteValue += 24.0
            default:
                break
            }
            switch self.beat.voice.bar.clefOttava {
            case Ottavia._15ma:
                noteValue -= 24.0
            case Ottavia._8va:
                noteValue -= 12.0
            case Ottavia.Regular:
                break
            case Ottavia._8vb:
                noteValue += 12.0
            case Ottavia._15mb:
                noteValue += 24.0
            default:
                break
            }
            return noteValue - self.beat.voice.bar.staff.displayTranspositionPitch
        }
    }

