                            self.bendType = BendType.Prebend
                            points!.splice(2.0, 1.0)
                            points!.splice(1.0, 1.0)
                        } else {
                            self.bendType = BendType.Hold
                            points!.splice(2.0, 1.0)
                            points!.splice(1.0, 1.0)
                        }
                    }
                } else {
                    Logger.warning("Model", "Unsupported bend type detected, fallback to custom", nil)
                }
            } else if points!.length == 3.0 {
                let origin: BendPoint = points![0]
                let middle: BendPoint = points![1]
                let destination: BendPoint = points![2]
                if destination.value > origin.value {
                    if middle.value > destination.value {
                        self.bendType = BendType.BendRelease
                        points!.splice(1.0, 0.0, BendPoint(middle.offset, middle.value))
                    } else if !self.isContinuedBend && origin.value > 0 {
                        self.bendType = BendType.PrebendBend
                        points!.splice(1.0, 1.0)
                    } else {
                        self.bendType = BendType.Bend
                        points!.splice(1.0, 1.0)
                    }
                } else if destination.value < origin.value {
                    if self.isContinuedBend {
                        self.bendType = BendType.Release
                        points!.splice(1.0, 1.0)
                    } else {
                        self.bendType = BendType.PrebendRelease
                        points!.splice(1.0, 1.0)
                    }
                } else {
                    if middle.value > origin.value {
                        self.bendType = BendType.BendRelease
                        points!.splice(1.0, 0.0, BendPoint(middle.offset, middle.value))
                    } else if origin.value > 0 && !self.isContinuedBend {
                        self.bendType = BendType.Prebend
                        points!.splice(1.0, 1.0)
                    } else {
                        self.bendType = BendType.Hold
                        points!.splice(1.0, 1.0)
                    }
                }
            } else if points!.length == 2.0 {
                let origin: BendPoint = points![0]
                let destination: BendPoint = points![1]
                if destination.value > origin.value {
                    if !self.isContinuedBend && origin.value > 0 {
                        self.bendType = BendType.PrebendBend
                    } else {
                        self.bendType = BendType.Bend
                    }
                } else if destination.value < origin.value {
                    if self.isContinuedBend {
                        self.bendType = BendType.Release
                    } else {
                        self.bendType = BendType.PrebendRelease
                    }
                } else {
                    if origin.value > 0 && !self.isContinuedBend {
                        self.bendType = BendType.Prebend
                    } else {
                        self.bendType = BendType.Hold
                    }
                }
            }
        }
        if self.initialBendValue > 0 {
            self.accidentalMode = NoteAccidentalMode.Default
        }
    }

    private static let _maxOffsetForSameLineSearch: Double = 3.0

    public static func nextNoteOnSameLine(_ note: Note) -> Note? {
        var nextBeat: Beat? = note.beat.nextBeat
        while TypeHelper.isTruthy(TypeHelper.isTruthy(nextBeat) && nextBeat!.voice.bar.index <= note.beat.voice.bar.index + Note._maxOffsetForSameLineSearch) {
            let noteOnString: Note? = nextBeat!.getNoteOnString(note.string)
            if TypeHelper.isTruthy(noteOnString) {
                return noteOnString!
            }
            nextBeat = nextBeat!.nextBeat
        }
        return nil
    }

    public static func findHammerPullDestination(_ note: Note) -> Note? {
        var nextBeat: Beat? = note.beat.nextBeat
        while TypeHelper.isTruthy(TypeHelper.isTruthy(nextBeat) && nextBeat!.voice.bar.index <= note.beat.voice.bar.index + Note._maxOffsetForSameLineSearch) {
            var noteOnString: Note? = nextBeat!.getNoteOnString(note.string)
            if TypeHelper.isTruthy(noteOnString) {
                return noteOnString!
            }
            do {
                var str: Double = note.string
                while str > 0 {
                    noteOnString = nextBeat!.getNoteOnString(str)
                    if TypeHelper.isTruthy(noteOnString) {
                        if noteOnString!.isLeftHandTapped {
                            return noteOnString!
                        }
                        break
                    }
                    str -= 1
                }
            }
            do {
                var str: Double = note.string
                while str <= note.beat.voice.bar.staff.tuning.length {
                    noteOnString = nextBeat!.getNoteOnString(str)
                    if TypeHelper.isTruthy(noteOnString) {
                        if noteOnString!.isLeftHandTapped {
                            return noteOnString!
                        }
                        break
                    }
                    str += 1
                }
            }
            nextBeat = nextBeat!.nextBeat
        }
        return nil
    }

    public static func findTieOrigin(_ note: Note) -> Note? {
        var previousBeat: Beat? = note.beat.previousBeat
        while TypeHelper.isTruthy(TypeHelper.isTruthy(previousBeat) && previousBeat!.voice.bar.index >= note.beat.voice.bar.index - Note._maxOffsetForSameLineSearch) {
            if note.isStringed {
                let noteOnString: Note? = previousBeat!.getNoteOnString(note.string)
                if TypeHelper.isTruthy(noteOnString) {
                    return noteOnString!
                }
            } else {
                if Number.isNaN(note.octave) && Number.isNaN(note.tone) {
                    if note.index < previousBeat!.notes.length {
                        return previousBeat!.notes[(note.index).toInt()]
                    }
                } else {
                    let noteWithValue: Note? = previousBeat!.getNoteWithRealValue(note.realValue)
                    if TypeHelper.isTruthy(noteWithValue) {
                        return noteWithValue!
                    }
                }
            }
            previousBeat = previousBeat!.previousBeat
        }
        return nil
    }

    nonisolated(unsafe) private static var _noteIdLookupKey: String = "NoteIdLookup"

    private var _noteIdBag: NoteIdBag? = nil

    public func chain(_ sharedDataBag: Map<String, Any?>? = nil) {
        if sharedDataBag == nil {
            return
        }
        if self._noteIdBag != nil {
            var noteIdLookup: Map<Double, Note>
            if sharedDataBag!.has(Note._noteIdLookupKey) {
                noteIdLookup = (sharedDataBag!.get(Note._noteIdLookupKey) as! Map<Double, Note>)
            } else {
                noteIdLookup = Map<Double, Note>()
                sharedDataBag!.set(Note._noteIdLookupKey, noteIdLookup)
            }
            if self._noteIdBag!.hammerPullDestinationNoteId != -1.0 || self._noteIdBag!.tieDestinationNoteId != -1.0 || self._noteIdBag!.slurDestinationNoteId != -1.0 || self._noteIdBag!.slideTargetNoteId != -1.0 {
                noteIdLookup.set(self.id, self)
            }
            if self._noteIdBag!.hammerPullOriginNoteId != -1.0 {
                self.hammerPullOrigin = noteIdLookup.get(self._noteIdBag!.hammerPullOriginNoteId)!
                self.hammerPullOrigin!.hammerPullDestination = self
            }
            if self._noteIdBag!.tieOriginNoteId != -1.0 {
                self.tieOrigin = noteIdLookup.get(self._noteIdBag!.tieOriginNoteId)!
                self.tieOrigin!.tieDestination = self
            }
            if self._noteIdBag!.slurOriginNoteId != -1.0 {
                self.slurOrigin = noteIdLookup.get(self._noteIdBag!.slurOriginNoteId)!
                self.slurOrigin!.slurDestination = self
            }
            if self._noteIdBag!.slideOriginNoteId != -1.0 {
                self.slideOrigin = noteIdLookup.get(self._noteIdBag!.slideOriginNoteId)!
                self.slideOrigin!.slideTarget = self
            }
            self._noteIdBag = nil
        } else {
            if !self.isTieDestination && self.tieOrigin == nil {
                return
            }
            let tieOrigin: Note? = self.tieOrigin ?? Note.findTieOrigin(self)
            if !TypeHelper.isTruthy(tieOrigin) {
                self.isTieDestination = false
            } else {
                tieOrigin!.tieDestination = self
                self.tieOrigin = tieOrigin!
                self.fret = tieOrigin!.fret
                self.octave = tieOrigin!.octave
                self.tone = tieOrigin!.tone
                if tieOrigin!.hasBend {
                    self.bendOrigin = self.tieOrigin!
                }
            }
        }
    }

    internal func toJson(_ o: Map<String, Any?>) {
        if self.tieDestination != nil {
            o.set("tiedestinationnoteid", self.tieDestination!.id)
        }
        if self.tieOrigin != nil {
            o.set("tieoriginnoteid", self.tieOrigin!.id)
        }
        if self.slurDestination != nil {
            o.set("slurdestinationnoteid", self.slurDestination!.id)
        }
        if self.slurOrigin != nil {
            o.set("sluroriginnoteid", self.slurOrigin!.id)
        }
        if self.hammerPullOrigin != nil {
            o.set("hammerpulloriginnoteid", self.hammerPullOrigin!.id)
        }
        if self.hammerPullDestination != nil {
            o.set("hammerpulldestinationnoteid", self.hammerPullDestination!.id)
        }
        if self.slideTarget != nil {
            o.set("slidetargetnoteid", self.slideTarget!.id)
        }
        if self.slideOrigin != nil {
            o.set("slideoriginnoteid", self.slideOrigin!.id)
        }
    }

    internal func setProperty(_ property: String, _ v: Any?) -> Bool {
        switch property {
        case "tiedestinationnoteid":
            if self._noteIdBag == nil {
                self._noteIdBag = NoteIdBag()
            }
            self._noteIdBag!.tieDestinationNoteId = TypeHelper.unknownToNumber(v)
            return true
        case "tieoriginnoteid":
            if self._noteIdBag == nil {
                self._noteIdBag = NoteIdBag()
            }
            self._noteIdBag!.tieOriginNoteId = TypeHelper.unknownToNumber(v)
            return true
        case "slurdestinationnoteid":
            if self._noteIdBag == nil {
                self._noteIdBag = NoteIdBag()
            }
            self._noteIdBag!.slurDestinationNoteId = TypeHelper.unknownToNumber(v)
            return true
        case "sluroriginnoteid":
            if self._noteIdBag == nil {
                self._noteIdBag = NoteIdBag()
            }
            self._noteIdBag!.slurOriginNoteId = TypeHelper.unknownToNumber(v)
            return true
        case "hammerpulloriginnoteid":
            if self._noteIdBag == nil {
                self._noteIdBag = NoteIdBag()
            }
            self._noteIdBag!.hammerPullOriginNoteId = TypeHelper.unknownToNumber(v)
            return true
        case "hammerpulldestinationnoteid":
            if self._noteIdBag == nil {
                self._noteIdBag = NoteIdBag()
            }
            self._noteIdBag!.hammerPullDestinationNoteId = TypeHelper.unknownToNumber(v)
            return true
        case "slidetargetnoteid":
            if self._noteIdBag == nil {
                self._noteIdBag = NoteIdBag()
            }
            self._noteIdBag!.slideTargetNoteId = TypeHelper.unknownToNumber(v)
            return true
        case "slideoriginnoteid":
            if self._noteIdBag == nil {
                self._noteIdBag = NoteIdBag()
            }
            self._noteIdBag!.slideOriginNoteId = TypeHelper.unknownToNumber(v)
            return true
        default:
            break
        }
        return false
    }

    public init() {}
}

/**
 * Lists all graphical sub elements within a  which can be styled via
 */
public enum NoteSubElement: Int, IAlphaTabEnum, CaseIterable {
    /**
     * The effects and annotations shown in dedicated effect bands above the staves (e.g. vibrato).
     * The style of the first note with the effect wins.
     */
    case Effects = 0
    /**
     * The note head on the standard notation staff.
     */
    case StandardNotationNoteHead = 1
    /**
     * The accidentals on the standard notation staff.
     */
    case StandardNotationAccidentals = 2
    /**
     * The effects and annotations applied to this note on the standard notation staff (e.g. bends).
     * If effects on beats result in individual note elements shown, this color will apply.
     */
    case StandardNotationEffects = 3
    /**
     * The fret number on the guitar tab staff.
     */
    case GuitarTabFretNumber = 4
    /**
     * The effects and annotations applied to this note on the guitar tab staff (e.g. bends).
     * If effects on beats result in individual note elements shown, this color will apply.
     */
    case GuitarTabEffects = 5
    /**
     * The note head on the slash notation staff.
     */
    case SlashNoteHead = 6
    /**
     * The effects and annotations applied to this note on the slash notation staff (e.g. dots).
     * If effects on beats result in individual note elements shown, this color will apply.
     */
    case SlashEffects = 7
    /**
     * The note number on the numbered notation staff.
     */
    case NumberedNumber = 8
    /**
     * The accidentals on the numbered notation staff.
     */
    case NumberedAccidentals = 9
    /**
     * The effects and annotations applied to this note on the number notation staff (e.g. dots).
     * If effects on beats result in individual note elements shown, this color will apply.
     */
    case NumberedEffects = 10
}

/**
 * Defines the custom styles for notes.
 */
public final class NoteStyle: ElementStyle<NoteSubElement> {
    /**
     * The symbol that should be used as note head.
     */
    public var noteHead: MusicFontSymbol? = nil

    /**
     * Whether the note head symbol should be centered on the stem (e.g. for arrow notes)
     */
    public var noteHeadCenterOnStem: Bool? = nil

    public override init() {
        super.init()
    }
}

internal final class NoteIdBag {
    public var tieDestinationNoteId: Double = -1.0

    public var tieOriginNoteId: Double = -1.0

    public var slurDestinationNoteId: Double = -1.0

    public var slurOriginNoteId: Double = -1.0

    public var hammerPullDestinationNoteId: Double = -1.0

    public var hammerPullOriginNoteId: Double = -1.0

    public var slideTargetNoteId: Double = -1.0

    public var slideOriginNoteId: Double = -1.0

    public init() {}
}
